package com.example.starter.runway;

/**
 * 跑道事件类型：FOD=外来物，PAVEMENT_DAMAGE=道面破损。接报任一类型即触发临时关闭。
 */
public enum EventType {
    FOD,
    PAVEMENT_DAMAGE
}

package com.example.starter.runway;

/**
 * 跑道事件状态机：CLOSED临时关闭 → INSPECTING巡检中 → ASSESSED已评估 →
 * REOPENED已恢复 / 持续关闭（仍为ASSESSED且最近评估不合格） → ARCHIVED归档（终态）。
 */
public enum EventStatus {
    CLOSED,
    INSPECTING,
    ASSESSED,
    REOPENED,
    ARCHIVED
}

package com.example.starter.runway;

/**
 * 评估类型：CLEAR_TO_REOPEN=清除即可恢复；REPAIR_REQUIRED=修复后恢复（须复测合格方可开放）。
 */
public enum AssessmentType {
    CLEAR_TO_REOPEN,
    REPAIR_REQUIRED
}

package com.example.starter.runway;

/**
 * 航行通告动作：CLOSE=临时关闭通告，REOPEN=恢复开放通告。
 */
public enum NotamAction {
    CLOSE,
    REOPEN
}

package com.example.starter.runway;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码与稳定错误码，由全局异常处理器转为统一错误报文。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "EVENT_NOT_FOUND", message);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    public static ApiException unprocessable(String code, String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message);
    }
}

