@Component
public class IdempotencyExecutor {
    private final IdempotencyRepository repo;
    private final ObjectMapper om;

    @Transactional
    public <T> T execute(String scope, String requestId, String fingerprint, Supplier<T> action, Class<T> type) {
        var existing = repo.find(scope, requestId);
        if (existing.isPresent()) {
            IdemRow row = existing.get();
            if (!row.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("IDEMPOTENCY_CONFLICT", "相同 requestId 的业务参数不一致");
            }
            return read(row.responseBody(), type);
        }
        T result = action.get();
        repo.insert(scope, requestId, fingerprint, write(result));
        return result;
    }

    public <T> T replayAfterDuplicate(String scope, String requestId, String fingerprint, Class<T> type) {
        // called after DuplicateKeyException, in a new transaction (propagation REQUIRES_NEW? original tx rolled back)
        var row = repo.find(scope, requestId).orElseThrow(() -> ApiException.conflict("IDEMPOTENCY_CONFLICT", ...));
        if (!row.fingerprint().equals(fingerprint)) throw conflict;
        return read(row.responseBody(), type);
    }
}
